import {chapterArt} from './chapter-art.mjs';
import {typeImages} from './type-images.mjs';
import {userTypeCopy} from './user-type-copy.mjs';
import {buildReport,reportScene,chapterSummaries} from './report.mjs';
import {axes,questions} from './model.mjs';
export function referenceDemoAnswers(code='INTP',stress='A'){
 const letters=code.split('').concat(stress),strengths=[[1,2,1,2,1,2,2,1,1,2,1,2],[3,2,2,3,1,2,2,2,1,2,2,1],[1,1,0,2,1,1,1,0,1,2,1,1],[3,1,1,2,2,1,2,1,2,1,1,2],[2,1,1,0,1,2,1,1,1,2,0,1]];
 const used={};return Object.fromEntries(questions.map(q=>{if(q.source==='original'){const ai=axes.findIndex(a=>a.id===q.axis),n=used[q.axis]||0;used[q.axis]=n+1;return [q.id,strengths[ai][n]*q.direction*(axes[ai].letters[0]===letters[ai]?1:-1)];}const index=Number(q.id.replace('ipip',''))-1;const ai=index%5;const preference=ai===0?(letters[0]==='I'?-1:1):ai===3?(stress==='A'?1:-1):1;return [q.id,((index%3)+1)*q.direction*preference];}));
}
export const referenceChapters=[['traits','人格特征'],['work','你的职业道路'],['growth','你的个人成长'],['relations','你的人际关系']];
export function laboratoryScene(){return `<svg class="neris-illustration" viewBox="0 0 920 420" role="img" aria-label="原创几何插画：探索者在实验室中研究想法"><path d="M97 333 282 269 743 288 853 350 596 407 230 393Z" fill="#dcd5e5"/><path d="M288 79 554 35 674 109 410 153Z" fill="#eee8f5"/><path d="m288 79 122 74v160l-122-69Z" fill="#d8cce7"/><path d="m410 153 264-44v164l-264 40Z" fill="#f4eff8"/><path d="m540 135 94-15v94l-94 17Z" fill="#b5a2ce"/><path d="m549 143 76-11v73l-76 13Z" fill="#e0e9e6"/><path d="m586 138 1 74m-38-33 76-13" stroke="#b5a2ce" stroke-width="5"/><path d="m242 203 186 35 247-33-180-36Z" fill="#9b83b1"/><path d="m242 203 186 35v23l-186-34Z" fill="#806698"/><path d="m428 238 247-33v23l-247 31Z" fill="#715a87"/><path d="m263 230 20 4v101l-20-5Zm363 8 20-3v100l-20 5Z" fill="#a58bb8"/><path d="m477 168 67-10v56l-67 10Z" fill="#594c6d"/><path d="m484 174 53-8v40l-53 9Z" fill="#c0d8d4"/><path d="m498 221 2 15 39-6-1-7-25 4v-9Z" fill="#756383"/><path d="m290 169 50 9 1 30-51-10Z" fill="#f5ead0"/><path d="m299 161 50 10-8 15-51-10Z" fill="#d2b97d"/><path d="m566 170 34-5 13 33-51 8Z" fill="#c3e5df"/><path d="m579 148 9-2 1 23 10 24-24 4 8-27Z" fill="#8ebcbb"/><path d="m727 233 45-9 35 14-44 10Z" fill="#b6c7be"/><path d="m727 233 36 15v53l-36-13Z" fill="#99b5a3"/><path d="m763 248 44-10v53l-44 10Z" fill="#739783"/><path d="M763 233V143m0 37-31-28m31 50 29-30" fill="none" stroke="#8d9b89" stroke-width="7"/><path d="m715 121 43 9-24 44-31-24Z" fill="#adc1a4"/><path d="m778 142 39-22 4 39-39 26Z" fill="#96b38e"/><path d="m745 106 18-32 25 36-22 45Z" fill="#bed0b1"/><path d="m178 316 34-5 35 16-35 9Z" fill="#f5e8b8"/><path d="m178 316 34 20v45l-34-19Z" fill="#d6c391"/><path d="m212 336 35-9v44l-35 10Z" fill="#b7a273"/><path d="m360 268 34 8-19 78-22-3Z" fill="#4f4b66"/><path d="m393 274 27-4 17 76-24 8Z" fill="#66617a"/><path d="m351 346 23 6-2 14-40-5Zm62 2 22-4 19 17-38 6Z" fill="#443f56"/><path d="m357 196 38-13 30 18 5 73-40 16-43-26Z" fill="#f9f7fc"/><path d="m357 196 29 45 4 49-43-26Z" fill="#e1d9ec"/><path d="m395 185-9 56 17-12 22-28Z" fill="#d9cce7"/><path d="m380 196 6 45 9-16 5-36Z" fill="#8c729f"/><path d="m365 144 37-11 17 20-6 36-28 17-24-24Z" fill="#e3b18b"/><path d="m364 145-10 18 14 18 2-23 33-9 13 17 9-15-22-27-32 8Z" fill="#6e687d"/><path d="m365 144 17-3 20-17-31 8Z" fill="#8c849b"/><path d="m361 205-21 43-40-16-9 13 53 24 16-8 25-47Z" fill="#e8e2f0"/><path d="m303 233-17-13-12 4 5 13 20 9Z" fill="#e3b18b"/><path d="m421 206 31 23 29-33 12 12-34 43-17 0-33-27Z" fill="#fcfaff"/><path d="m479 195 11-19 10 2 0 14-9 14Z" fill="#e3b18b"/><path d="m478 168 9-22 15 22-12 15Z" fill="#e8ca7f"/><circle cx="195" cy="150" r="38" fill="none" stroke="#c2b1d3" stroke-width="3"/><ellipse cx="195" cy="150" rx="15" ry="38" fill="none" stroke="#c2b1d3" stroke-width="3" transform="rotate(40 195 150)"/><ellipse cx="195" cy="150" rx="15" ry="38" fill="none" stroke="#c2b1d3" stroke-width="3" transform="rotate(-40 195 150)"/><circle cx="195" cy="150" r="6" fill="#b197c7"/><path d="m692 66 18 10-18 10-18-10Z" fill="#c4b0d6"/><path d="M247 78v-20m-10 10h20M721 320v-18m-9 9h18" stroke="#d2bd87" stroke-width="3"/><path d="m115 274 16-18 18 18-18 20Z" fill="#b7cfc6"/><path d="m639 365 42-8 19 10-44 9Z" fill="#c3b4d4"/></svg>`;}
const refIcon=(name)=>{const paths={download:'<path d="M12 3v12m-5-5 5 5 5-5M5 15v6h14v-6"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M6 10H3v11h18V10h-3"/>',chart:'<circle cx="12" cy="12" r="9"/><path d="M12 3v9h9"/>',bars:'<path d="M3 6h18M3 12h18M3 18h18M8 3v6m8 0v6M7 15v6"/>',heart:'<path d="M12 21S2 15 2 8a5 5 0 0 1 10-2 5 5 0 0 1 10 2c0 7-10 13-10 13Z"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.share}</svg>`;};
function refList(items,mode){return `<div class="nr-points">${items.map(g=>`<article><span class="nr-check" aria-hidden="true">${mode==='strength'?'✓':'−'}</span><div><h4>${g[mode==='strength'?'strength':'risk']}</h4><p>${g[mode==='strength'?'detail':'riskDetail']}</p></div></article>`).join('')}</div>`;}
const summaryMarkup=(key,text)=>`<div class="nr-summary" data-chapter-summary="${key}">${text.split("\n\n").map(paragraph=>`<p>${paragraph}</p>`).join('')}</div>`;
const copyEscape=text=>text.replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function userIntroduction(result,fallback){
 const code=result.code.split('-')[0],copy=userTypeCopy[code];
 if(!copy||result.dimensions.slice(0,4).some(d=>d.boundary))return summaryMarkup('traits',fallback);
 return `<div class="nr-summary nr-type-copy" data-chapter-summary="traits">${copy.blocks.map(block=>{const text=copyEscape(block.text);if(block.kind==='heading')return `<h3>${text}</h3>`;if(block.kind==='quote')return `<blockquote>${text.split('\n').map(line=>`<p>${line}</p>`).join('')}</blockquote>`;return `<p>${text}</p>`;}).join('')}</div>`;
}
function personalityImage(result,kind){
 const image=typeImages[result.code.split('-')[0]]?.[kind];
 if(!image)return kind==='avatar'?reportScene():laboratoryScene();
 return `<img class="nr-type-image nr-type-${kind}" src="${image.src}" alt="${copyEscape(image.alt)}" decoding="async" ${kind==='scene'?'loading="lazy"':''}>`;
}
export function referenceMarkup(result,{demo=false,base='INTP',stress='A',profiles={}}={}){
 const r=buildReport(result),d=result.dimensions,analyst=['NT'].includes(base.slice(1,3)),theme=analyst?'purple':base[1]==='N'?'green':'blue';
 const summaries=chapterSummaries(result);
 return `<article class="nr-report nr-${theme}">
 ${demo?`<div class="nr-demo"><span>示例报告 · 模拟作答</span><label>类型 <select id="demo-type" aria-label="切换示例人格类型">${Object.keys(profiles).map(c=>`<option ${c===base?'selected':''}>${c}</option>`).join('')}</select></label><label>压力倾向 <select id="demo-stress" aria-label="切换示例压力倾向"><option value="A" ${stress==='A'?'selected':''}>A</option><option value="T" ${stress==='T'?'selected':''}>T</option></select></label><button data-action="exit-demo">返回测试</button></div>`:''}
 <div class="nr-tools"><div class="nr-jump"><label for="nr-chapter-select" class="sr-only">报告章节</label><select id="nr-chapter-select">${referenceChapters.map(([id,label],i)=>`<option value="${id}">${i+1}. ${label}</option>`).join('')}</select></div><div class="nr-tool-actions"><button class="nr-icon-button" data-action="copy" aria-label="复制结果">${refIcon('share')}</button><button class="nr-icon-button" data-action="download" aria-label="下载报告">${refIcon('download')}</button></div></div>
 <section class="nr-hero"><p>你的人格类型是：</p><h1>${r.name}</h1><div class="nr-code">${result.code}</div><div class="nr-scene">${personalityImage(result,'avatar')}</div></section>
 <div class="nr-layout"><aside class="nr-sidebar"><p>你的性格报告</p><nav aria-label="报告目录">${referenceChapters.map(([id,label],i)=>`<a href="#nr-${id}" data-nr-nav="${id}" ${i===0?'aria-current="location"':''}><span>${i+1}</span>${label}<b>›</b></a>`).join('')}</nav><a class="nr-pill" href="#nr-full">下载完整报告</a><small>${result.code} · ${r.name}</small></aside>
 <div class="nr-content"><div class="nr-opening">${userIntroduction(result,summaries.traits)}</div>
 <section class="nr-section" id="nr-traits"><h2><span>1</span>人格特征</h2><div class="nr-trait-card"><div class="nr-trait-title"><h3>人格特征</h3><div role="group" aria-label="图表样式"><button data-nr-chart="bars" aria-label="条形图" aria-pressed="true">${refIcon('bars')}</button><button data-nr-chart="rings" aria-label="圆环图" aria-pressed="false">${refIcon('chart')}</button></div></div><div class="nr-bars">${d.map((axis,i)=>`<div class="nr-dimension" style="--axis:${axis.color};--position:${axis.leftPercent}%"><h4>${axis.name}：<strong>${axis.boundary?'接近中点':`${Math.max(axis.leftPercent,axis.rightPercent)}% ${axis.leftPercent>axis.rightPercent?axis.left:axis.right}`}</strong><button class="nr-help" data-nr-help="${i}" aria-label="了解${axis.name}">?</button></h4><div class="nr-bar" role="img" aria-label="${axis.name}：${axis.left} ${axis.leftPercent}%，${axis.right} ${axis.rightPercent}%"><i></i><span></span></div><div class="nr-range"><span>${axis.left}</span><span>${axis.right}</span></div></div>`).join('')}</div><div class="nr-rings" hidden>${d.map(axis=>`<div class="nr-ring-item"><div class="nr-ring" style="--axis:${axis.color};--degrees:${Math.max(axis.leftPercent,axis.rightPercent)*3.6}deg" role="img" aria-label="${axis.name} ${Math.max(axis.leftPercent,axis.rightPercent)}%"><strong>${Math.max(axis.leftPercent,axis.rightPercent)}<small>%</small></strong></div><h4>${axis.leftPercent>axis.rightPercent?axis.left:axis.right}</h4><span>${axis.name}</span></div>`).join('')}</div><p class="nr-chart-note">百分比表示你的回答更靠近哪一边，不是你超过了多少人。两边接近时，可以多看看自己在不同事情上的表现。</p></div></section>
 <section class="nr-section" id="nr-work"><h2><span>2</span>你的职业道路</h2><div class="nr-chapter-scene">${personalityImage(result,'scene')}</div>${summaryMarkup('work',summaries.work)}<h3 class="nr-subtitle">你的强项</h3>${refList(r.typeWorkPoints||r.selected.slice(0,4),'strength')}<h3 class="nr-subtitle">你的短板</h3><div class="nr-risks">${refList(r.typeWorkPoints||r.selected.slice(0,4),'risk')}</div></section>
 <section class="nr-section" id="nr-growth"><h2><span>3</span>你的个人成长</h2><div class="nr-chapter-scene nr-growth-scene">${chapterArt(result.code.split('-')[0],'growth')}</div>${summaryMarkup('growth',summaries.growth)}<h3 class="nr-subtitle">你可以发挥的力量</h3>${refList([r.selected[0],r.selected[1],r.selected[3],r.selected[4]],'strength')}</section>
 <section class="nr-section" id="nr-relations"><h2><span>4</span>你的人际关系</h2><div class="nr-chapter-scene nr-relations-scene">${chapterArt(result.code.split('-')[0],'relations')}</div>${summaryMarkup('relations',summaries.relations)}<div class="nr-relation-points">${[0,2,3,4].map((i,n)=>`<article><span>${['相处节奏','表达与倾听','约定与变化','压力中的支持'][n]}</span><h4>${r.selected[i].title}</h4><p>${r.selected[i].relationship}</p></article>`).join('')}</div></section>
 <section class="nr-full-report" id="nr-full"><span>把理解，带进日常生活</span><h2>你的故事，比字母更丰富。</h2><p>保存这份报告，回到真实经历里继续探索。</p><div><button class="nr-pill" data-action="download">下载完整报告 ${refIcon('download')}</button></div><small>本站报告全部可查看，无需付费解锁。</small></section></div></div>
 <nav class="nr-bottom-nav" aria-label="报告快捷导航"><a href="#nr-traits"><span>◈</span>结果</a><a href="#nr-work"><span>♧</span>职业</a><a href="#nr-growth"><span>✧</span>成长</a><a href="#nr-relations"><span>♡</span>关系</a><a href="#nr-full"><span>⇩</span>报告</a></nav></article>`;
}
